responseText:
root = Stack([
  instructionText,
  accountsSection,
  transferForm,
  successCallout,
  errorCallout
], "column", "l")

$amount = ""
$recipientName = ""
$memo = ""
$showSuccess = false
$lastTransferredAmount = ""
$lastTransferredRecipient = ""

accountsQuery = Query("host_listAccounts", {}, [])
transferMutation = Mutation("host_transferMoney", {amount: @ParseFloat($amount), recipient_name: $recipientName, memo: $memo})

instructionText = TextContent(
  "I can help you initiate a money transfer from your checking account to a named recipient. This action will debit your checking account.",
  "default"
)

accountsSection = Card([
  CardHeader("Your Accounts", "For reference, here are your current accounts and balances."),
  Stack(
    @Each(accountsQuery, "account",
      Stack([
        TextContent(account.name + " (" + account.mask + ")"),
        TextContent("$" + account.balance, "small-heavy")
      ], "row", "m", "center", "between")
    ), "column", "s"
  )
], "sunk")

amountField = FormControl("Amount", Input("amount", "e.g., 50.00", "number", {required: true, min: 0.01}, $amount))
recipientField = FormControl("Recipient Name", Input("recipientName", "Recipient's Full Name", "text", {required: true, minLength: 3}, $recipientName))
memoField = FormControl("Memo (Optional)", TextArea("memo", "For e.g., groceries, rent", 3, null, $memo))

transferButtons = Buttons([
  Button("Send Money", Action([
    // Capture current values for success message BEFORE running mutation
    @Set($lastTransferredAmount, $amount),
    @Set($lastTransferredRecipient, $recipientName),
    @Run(transferMutation),
    @Set($showSuccess, transferMutation.status == "success"),
    // Clear form fields only on successful transfer
    @Set($amount, transferMutation.status == "success" ? "" : $amount),
    @Set($recipientName, transferMutation.status == "success" ? "" : $recipientName),
    @Set($memo, transferMutation.status == "success" ? "" : $memo)
  ]), "primary"),
  Button("Cancel", Action([@Set($amount, ""), @Set($recipientName, ""), @Set($memo, ""), @Set($showSuccess, false)]), "tertiary")
], "row")

transferForm = Card([
  CardHeader("New Money Transfer"),
  Form("transferMoney", transferButtons, [
    amountField,
    recipientField,
    memoField
  ])
])

// The Callout component for success automatically sets $showSuccess to false after 3 seconds
successCallout = transferMutation.status == "success" ? Callout("success", "Transfer Successful", "Your transfer of $" + $lastTransferredAmount + " to " + $lastTransferredRecipient + " has been initiated.", $showSuccess) : null
errorCallout = transferMutation.status == "error" ? Callout("error", "Transfer Failed", "Something went wrong: " + transferMutation.error) : null

